  "docs.d0479": "Tool selection policy: \"auto\", \"none\", \"required\", or an object specifying a tool, {\"type\": \"function\" | \"custom\" | \"local_shell\", \"name\": \"...\"} (function / custom require name).",
  "docs.d0480": "Text output settings.",
